<section class="hero"><h1>Ankesat mbi faturat</h1><p>Ankesa kalon te koordinatori, komisioni, shqyrtimi dhe vendimi.</p></section>
<section class="panel"><h2>Paraqit ankesë</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf->token())?>"><div class="detail-grid"><label class="field">Fatura<select name="invoice_id" required><option value="">Zgjidhni</option><?php foreach($invoices as $invoice):?><option value="<?=(int)$invoice['id']?>"><?=e($invoice['invoice_number'].' — '.$invoice['business_name'])?></option><?php endforeach;?></select></label><label class="field">Titulli<input name="subject" maxlength="200" required></label><label class="field">Përshkrimi<textarea name="appeal_text" maxlength="10000" rows="6" required></textarea></label></div><div class="actions"><button>Dërgo ankesën</button></div></form></section>
<section class="panel"><h2>Ankesat e mia</h2><div class="table-wrap"><table><thead><tr><th>Fatura</th><th>Biznesi</th><th>Titulli</th><th>Statusi</th><th>Data</th><th>Vendimi</th></tr></thead><tbody><?php foreach($appeals as $appeal):?><tr><td><?=e($appeal['invoice_number'])?></td><td><?=e($appeal['business_name'])?></td><td><?=e($appeal['subject'])?></td><td><span class="badge"><?=e($appeal['status_code'])?></span></td><td><?=e($appeal['submitted_at'])?></td><td><?=e($appeal['decision_text']??'—')?></td></tr><?php endforeach;?></tbody></table><?php if($appeals===[]):?><div class="empty">Nuk ka ankesa.</div><?php endif;?></div></section>
